Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='phonereplica', at=datetime(2026, 9, 5, 0, 0, 0), actor='assistant', title='The phone is a replica: an act is sealed in the tab and folded from what the browser holds', body="*The phone is a replica* (0.13.x, ARCHITECTURE §5): an act is sealed in the tab and folded from what the browser holds — nothing optimistic, nothing rolled back, no queue, nonce or base tip. A REFUSED object stays local and NAMED, never retried; the one escape (reset the replica from the box) says first what it loses. The phone cannot author (the markup door, the FPL term, the derived id and `confirm_todo`'s refusals are `suzatary-core`'s), so `add`/`confirm` ask `POST /api/author`. `GET /api/me` → `actor: null` means no act controls.", rationale='Since 0.13.0, 2026-09-05 (ARCHITECTURE §5).', supersedes=()))